const fs=require('fs'), path=require('path'), home=process.env.HOME;
for (const name of ['pi-subagents','pi-mcp-adapter','@modelcontextprotocol/sdk','@hono/node-server','@modelcontextprotocol/ext-apps']) {
 const p=path.join(home,'.pi/agent/npm/node_modules',name,'package.json');
 try { const m=JSON.parse(fs.readFileSync(p)); console.log(name+'@'+m.version); } catch(e) { console.log(name+': absent'); }
}
NODE
printf '%s\n' '--- npm why ---'; cd "$HOME/.pi/agent/npm" && npm ls pi-subagents pi-mcp-adapter @modelcontextprotocol/sdk @hono/node-server @modelcontextprotocol/ext-apps --depth=4 2>&1 | sed -n '1,180p'

argsPayload:
{
  "command": "printf '%s\\n' '--- all ~/.pi symlinks into old example ---'; find \"$HOME/.pi/agent\" -type l -print 2>/dev/null | while IFS= read -r p; do t=$(readlink \"$p\"); case \"$t\" in *'@earendil-works/pi-coding-agent/examples/extensions/subagent'*) printf '%s -> %s\\n' \"$p\" \"$t\";; esac; done; printf '%s\\n' '--- old path text refs ---'; grep -RIn --exclude-dir=sessions --exclude-dir=node_modules --exclude='*.log' -E '@earendil-works/pi-coding-agent/examples/extensions/subagent|@tintinweb/pi-subagents|npm:pi-subagents' \"$HOME/.pi/agent\" 2>/dev/null | head -100 || true",
  "timeout": 60
}

{
  "command": "printf '%s\\n' '--- all installed package roots ---'; for p in \"$HOME/.pi/agent/npm/node_modules\"/*; do [ -d \"$p\" ] || continue; printf '%s\\n' \"$(basename \"$p\")\"; done | sort; printf '%s\\n' '--- manifest references ---'; grep -RIn --include='package.json' --include='settings.json' --include='*.json' -E 'pi-subagents|tintinweb|earendil' \"$HOME/.pi/agent\" 2>/dev/null | head -150 || true",
  "timeout": 60
}

{
  "command": "printf '%s\\n' '--- pi settings files ---'; find \"$HOME/.pi/agent\" -maxdepth 2 -type f -name '*.json' -print 2>/dev/null | sort; printf '%s\\n' '--- likely settings ---'; for f in \"$HOME/.pi/agent/settings.json\" \"$HOME/.pi/agent/settings.local.json\" \"$HOME/.pi/agent/package.json\"; do if [ -f \"$f\" ]; then echo \"### $f\"; cat \"$f\"; fi; done",
  "timeout": 30
}

{
  "command": "printf '%s\n' '--- dependency versions ---'; node - <<'NODE'
const fs=require('fs'), path=require('path'), home=process.env.HOME;
for (const name of ['pi-subagents','pi-mcp-adapter','@modelcontextprotocol/sdk','@hono/node-server','@modelcontextprotocol/ext-apps']) {
 const p=path.join(home,'.pi/agent/npm/node_modules',name,'package.json');
 try { const m=JSON.parse(fs.readFileSync(p)); console.log(name+'@'+m.version); } catch(e) { console.log(name+': absent'); }
}
NODE
printf '%s\n' '--- npm why ---'; cd "$HOME/.pi/agent/npm" && npm ls pi-subagents pi-mcp-adapter @modelcontextprotocol/sdk @hono/node-server @modelcontextprotocol/ext-apps --depth=4 2>&1 | sed -n '1,180p'",
  "timeout": 60
}

{
  "command": "printf '%s\\n' '--- ~/.pi/agent/prompts ---'; ls -la \"$HOME/.pi/agent/prompts\" 2>&1; printf '%s\\n' '--- all prompt links ---'; find \"$HOME/.pi/agent/prompts\" -maxdepth 1 -type l -print -exec readlink {} \\; 2>/dev/null | sort; printf '%s\\n' '--- old example subagent target contents (read-only) ---'; base=$(dirname \"$(readlink \"$HOME/.pi/agent/prompts/implement.md\")\"); echo \"$base\"; find \"$base\" -maxdepth 2 -type f -print | sort | sed -n '1,100p'; printf '%s\\n' '--- pi-subagents resources ---'; p=\"$HOME/.pi/agent/npm/node_modules/pi-subagents\"; find \"$p\" -maxdepth 2 -type f \\( -path '*/prompts/*' -o -path '*/skills/*' -o -name 'index.ts' \\) -print | sort | sed -n '1,140p'",
  "timeout": 30
}

{
  "command": "set -o pipefail
pi --mode json -p --no-session --tools subagent 'Call the subagent tool with action="list" and return the tool result verbatim.' > /tmp/pi-subagent-smoke-live.json 2>/tmp/pi-subagent-smoke-live.stderr
rc=$?
printf 'rc=%s\n' "$rc"
printf '%s\n' '--- stderr ---'
cat /tmp/pi-subagent-smoke-live.stderr
printf '%s\n' '--- extracted events ---'
node - <<'NODE'
const fs=require('fs');
const lines=fs.readFileSync('/tmp/pi-subagent-smoke-live.json','utf8').split(/\n/).filter(Boolean);
for (const line of lines) { try { const e=JSON.parse(line); if (e.type==='tool_execution_start'||e.type==='tool_execution_end'||e.type==='message_end'||e.type==='agent_end') console.log(JSON.stringify(e)); } catch {} }
NODE
exit $rc",
  "timeout": 180
}

